import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Button, Typography } from 'antd';
import cn from 'classnames';

import page404 from 'assets/images/errorPages/404.svg';
import { EMainRoutes } from 'shared/typings';
import { Page } from 'shared/ui';

import styles from './NotFound.module.scss';

interface INotFoundProps extends HTMLAttributes<HTMLDivElement> {}

export const NotFound: FC<INotFoundProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();

	return (
		<Page {...props} className={cn(className)} withoutHeading>
			<div className={cn(styles.notFound)}>
				<img className={styles.notFound__img} src={page404} alt={t('Страница не найдена')} width="330" height="212" />
				<div>
					<Typography.Title level={4} className={styles.notFound__title}>
						{t('Страница не найдена')}
					</Typography.Title>
					<Typography.Paragraph className={styles.notFound__text} type="secondary">
						{t('Запрашиваемый URL-адрес не найден.')}
						<br />
						{t('Возможно, вы допустили опечатку, а может быть, этой страницы никогда не существовало')}
					</Typography.Paragraph>
					{/*TODO: navigate to Link */}
					<Button className={styles.notFound__link} onClick={() => navigate(EMainRoutes.DASHBOARD)} size={'large'}>
						{t('Перейти на главную')}
					</Button>
				</div>
			</div>
		</Page>
	);
};

export default NotFound;
